#include <vector>
#include <cstdint>

// Pretend we are on a 64-bit system where size_t is 64 bits
// and unsigned int is 32 bits.
std::vector<int> v;
// ... v gets filled with more than 2^32 elements ...

// Incorrect 'type shortcut': sz could be too small.
unsigned int sz_incorrect = v.size(); // Potential truncation if v.size() > UINT_MAX

// Correct and robust: sz's type is std::vector<int>::size_type
auto sz_correct = v.size(); // Type is guaranteed to be correct

static_assert(!std::is_same_v<decltype(sz_incorrect), decltype(sz_correct)>,
              "Types may differ and cause bugs");
